PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,public_id TEXT NOT NULL UNIQUE,username TEXT NOT NULL UNIQUE,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,password_iterations INTEGER NOT NULL DEFAULT 180000,role TEXT NOT NULL DEFAULT 'user',plan TEXT NOT NULL DEFAULT 'free',verified INTEGER NOT NULL DEFAULT 0,profile_color TEXT NOT NULL DEFAULT '#ffd400',tap_skin TEXT NOT NULL DEFAULT 'danfo',sound_on INTEGER NOT NULL DEFAULT 1,orientation TEXT NOT NULL DEFAULT 'center',funded_balance INTEGER NOT NULL DEFAULT 0,earned_balance INTEGER NOT NULL DEFAULT 0,lifetime_taps INTEGER NOT NULL DEFAULT 0,raw_lifetime_taps INTEGER NOT NULL DEFAULT 0,referral_code TEXT NOT NULL UNIQUE,referred_by INTEGER,failed_attempts INTEGER NOT NULL DEFAULT 0,lock_until INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(referred_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_sessions_exp ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS pools (id INTEGER PRIMARY KEY AUTOINCREMENT,public_id TEXT NOT NULL UNIQUE,creator_user_id INTEGER NOT NULL,title TEXT NOT NULL,description TEXT,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,entry_fee INTEGER NOT NULL DEFAULT 0,prize_seed INTEGER NOT NULL DEFAULT 0,prize_pool INTEGER NOT NULL DEFAULT 0,boosters_allowed INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL,FOREIGN KEY(creator_user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_pools_dates ON pools(start_at,end_at);
CREATE TABLE IF NOT EXISTS pool_members (id INTEGER PRIMARY KEY AUTOINCREMENT,pool_id INTEGER NOT NULL,user_id INTEGER NOT NULL,paid_amount INTEGER NOT NULL DEFAULT 0,joined_at INTEGER NOT NULL,left_at INTEGER,total_taps INTEGER NOT NULL DEFAULT 0,raw_taps INTEGER NOT NULL DEFAULT 0,boosted_taps INTEGER NOT NULL DEFAULT 0,UNIQUE(pool_id,user_id),FOREIGN KEY(pool_id) REFERENCES pools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS boosters (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,multiplier REAL NOT NULL DEFAULT 1,tap_limit INTEGER NOT NULL DEFAULT 100,price INTEGER NOT NULL DEFAULT 0,mega_only INTEGER NOT NULL DEFAULT 0,icon TEXT NOT NULL DEFAULT '⚡',image_url TEXT,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_boosters (user_id INTEGER NOT NULL,booster_id INTEGER NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,booster_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(booster_id) REFERENCES boosters(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS active_pool_boosters (user_id INTEGER NOT NULL,pool_id INTEGER NOT NULL,booster_id INTEGER NOT NULL,remaining_taps INTEGER NOT NULL,PRIMARY KEY(user_id,pool_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(pool_id) REFERENCES pools(id) ON DELETE CASCADE,FOREIGN KEY(booster_id) REFERENCES boosters(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tap_events (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,pool_id INTEGER NOT NULL,raw_taps INTEGER NOT NULL DEFAULT 1,credited_taps INTEGER NOT NULL DEFAULT 1,booster_id INTEGER,created_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(pool_id) REFERENCES pools(id) ON DELETE CASCADE,FOREIGN KEY(booster_id) REFERENCES boosters(id));
CREATE INDEX IF NOT EXISTS idx_taps_user_time ON tap_events(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_taps_pool_time ON tap_events(pool_id,created_at);
CREATE TABLE IF NOT EXISTS referrals (id INTEGER PRIMARY KEY AUTOINCREMENT,inviter_user_id INTEGER NOT NULL,invitee_user_id INTEGER NOT NULL UNIQUE,created_at INTEGER NOT NULL,FOREIGN KEY(inviter_user_id) REFERENCES users(id),FOREIGN KEY(invitee_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS wallet_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,kind TEXT NOT NULL,amount INTEGER NOT NULL,note TEXT,created_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS skins (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,price INTEGER NOT NULL DEFAULT 0,mega_only INTEGER NOT NULL DEFAULT 0,style TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS ads (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT,image_url TEXT,link_url TEXT,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS space_messages (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,message TEXT NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
